1450  jv jv_string_slice(jv j, int start, int end) {
  1451    assert(JVP_HAS_KIND(j, JV_KIND_STRING));
  1452    const char *s = jv_string_value(j);
  1453    int len = jv_string_length_bytes(jv_copy(j));
  1454    int i;
  1455    const char *p, *e;
  1456    int c;
  1457    jv res;
  1458
  1459    jvp_clamp_slice_params(len, &start, &end);
  1460    assert(0 <= start && start <= end && end <= len);
  1461
  1462    /* Look for byte offset corresponding to start codepoints */
  1463    for (p = s, i = 0; i < start; i++) {
  1464      p = jvp_utf8_next(p, s + len, &c);
  1465      if (p == NULL) {
  1466        jv_free(j);
  1467        return jv_string_empty(16);
  1468      }
  1469      if (c == -1) {
  1470        jv_free(j);
  1471        return jv_invalid_with_msg(jv_string("Invalid UTF-8 string"));
  1472      }
  1473    }
  1474    /* Look for byte offset corresponding to end codepoints */
  1475    for (e = p; e != NULL && i < end; i++) {
  1476      e = jvp_utf8_next(e, s + len, &c);
  1477      if (e == NULL) {
  1478        e = s + len;
  1479        break;
  1480      }
  1481      if (c == -1) {
  1482        jv_free(j);
  1483        return jv_invalid_with_msg(jv_string("Invalid UTF-8 string"));
  1484      }
  1485    }
  1486
  1487    /*
  1488     * NOTE: Ideally we should do here what jvp_array_slice() does instead
  1489     * of allocating a new string as we do!  However, we assume NUL-
  1490     * terminated strings all over, and in the jv API, so for now we waste
  1491     * memory like a drunken navy programmer.  There's probably nothing we
  1492     * can do about it.
  1493     */
  1494    res = jv_string_sized(p, e - p);
  1495    jv_free(j);
  1496    return res;
  1497  }
